-- 0240_templates_2026_pack.sql
--
-- 2026 template pack — 12 platform templates that round out the
-- gallery for the post-AI / inbox-native era. The goal mix mirrors
-- the goal taxonomy introduced in 0187 (welcome / newsletter /
-- announcement / promotional / re_engagement / transactional /
-- automation) so every goal-filter tab in the dashboard ships with
-- multiple curated options instead of the single seed row carried
-- over from 0048.
--
-- Curation notes:
--
--   * Six of the twelve are flagged is_featured = true and float to
--     the top of the Postwave Gallery for first-run users. The mix
--     was picked so that every goal tab has at least one featured
--     hero and a quieter alternative.
--
--   * tenant_id is NULL on every row (platform-owned). The ON
--     CONFLICT clause keys on slug WHERE tenant_id IS NULL so re-
--     running the migration is a no-op and tenant-owned templates
--     that happen to share a slug are untouched.
--
--   * Style direction (2026): editorial / engineering-voice / honest
--     math / consent-first re-engagement / AI-reasoning automation.
--     HTML is hand-inlined, table-based, and Outlook-safe; long
--     bodies are SQL-concatenated with || across multiple lines for
--     readability and to keep diffs reviewable.
--
--   * variables is jsonb (::jsonb cast on a JSON array literal) and
--     tags is text[] (ARRAY[...]).
--
-- Idempotency: ON CONFLICT (slug) WHERE tenant_id IS NULL DO NOTHING
-- — matches the partial unique index on platform templates.

BEGIN;

INSERT INTO campaign_templates
    (tenant_id, slug, name, description, category, subject, preview_text,
     body_html, variables, tags, goal, is_featured)
VALUES

    -- 1. welcome-negative-promise
    (NULL, 'welcome-negative-promise',
     'Negative Welcome',
     'Anti-hype welcome that opens by listing what we WILL NOT do (no daily emails, no data sales, no nags) before stating the one thing we will do. Builds trust as a scarce post-AI resource.',
     'marketing',
     'you''re in. here''s what we won''t do.',
     'Three promises about what''s NOT going to happen in your inbox.',
     '<div style="background-color:#F5F1EA;padding:48px 16px;font-family:Georgia,''Times New Roman'',serif;">'
     || '<table role="presentation" width="600" align="center" cellpadding="0" cellspacing="0" border="0" style="width:600px;max-width:600px;margin:0 auto;background-color:#FFFFFF;border:1px solid #E6DFD2;border-radius:16px;">'
     || '<tr><td style="padding:56px 56px 24px 56px;font-family:Georgia,''Times New Roman'',serif;">'
     ||   '<div style="font-family:system-ui,-apple-system,''Segoe UI'',sans-serif;font-size:11px;letter-spacing:0.18em;text-transform:uppercase;color:#8A7F6E;font-weight:600;">A note from {{founder_name}}</div>'
     || '</td></tr>'
     || '<tr><td style="padding:0 56px 24px 56px;font-family:Georgia,''Times New Roman'',serif;">'
     ||   '<h1 style="margin:0;font-family:Georgia,''Times New Roman'',serif;font-size:56px;line-height:60px;letter-spacing:-0.02em;color:#1A1A1A;font-weight:400;text-transform:lowercase;">you&rsquo;re in.</h1>'
     ||   '<div style="margin-top:16px;font-family:Georgia,''Times New Roman'',serif;font-size:56px;line-height:60px;letter-spacing:-0.02em;color:#B8AC95;font-weight:400;text-transform:lowercase;">here&rsquo;s what we won&rsquo;t do.</div>'
     || '</td></tr>'
     || '<tr><td style="padding:24px 56px 0 56px;font-family:Georgia,''Times New Roman'',serif;font-size:17px;line-height:28px;color:#1A1A1A;">'
     ||   'Hi {{first_name}} &mdash; your <strong style="font-weight:600;">{{plan_name}}</strong> seat on {{product}} is active. No setup wizard, no 14-step onboarding email sequence. Just this letter, and the truth.'
     || '</td></tr>'
     || '<tr><td align="center" style="padding:40px 56px 32px 56px;font-family:Georgia,''Times New Roman'',serif;font-size:14px;letter-spacing:0.5em;color:#B8AC95;">* * *</td></tr>'
     || '<tr><td style="padding:0 56px 8px 56px;font-family:system-ui,-apple-system,''Segoe UI'',sans-serif;font-size:11px;letter-spacing:0.18em;text-transform:uppercase;color:#8A7F6E;font-weight:600;">Three promises</td></tr>'
     || '<tr><td style="padding:0 56px 0 56px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td valign="top" width="56" style="padding:24px 0 0 0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;letter-spacing:0.05em;color:#8A7F6E;font-weight:600;">01 /</td><td valign="top" style="padding:24px 0 0 0;font-family:Georgia,''Times New Roman'',serif;font-size:17px;line-height:28px;color:#1A1A1A;"><strong style="font-weight:600;">We won&rsquo;t send you a &ldquo;tips &amp; tricks&rdquo; drip.</strong><br /><span style="color:#5C544A;">No five-part course. No &ldquo;day 3 of 7.&rdquo; If we write, it&rsquo;s because something is genuinely new or genuinely useful.</span></td></tr><tr><td valign="top" style="padding:20px 0 0 0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;letter-spacing:0.05em;color:#8A7F6E;font-weight:600;">02 /</td><td valign="top" style="padding:20px 0 0 0;font-family:Georgia,''Times New Roman'',serif;font-size:17px;line-height:28px;color:#1A1A1A;"><strong style="font-weight:600;">We won&rsquo;t ask you for a testimonial in week one.</strong><br /><span style="color:#5C544A;">You haven&rsquo;t earned an opinion yet, and we haven&rsquo;t earned one from you. Maybe later. Maybe never. Both are fine.</span></td></tr><tr><td valign="top" style="padding:20px 0 0 0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;letter-spacing:0.05em;color:#8A7F6E;font-weight:600;">03 /</td><td valign="top" style="padding:20px 0 0 0;font-family:Georgia,''Times New Roman'',serif;font-size:17px;line-height:28px;color:#1A1A1A;"><strong style="font-weight:600;">We won&rsquo;t pretend this email is from a robot.</strong><br /><span style="color:#5C544A;">Hit reply. It goes to my actual inbox. I read every one, usually within a day, sometimes with typos.</span></td></tr></table></td></tr>'
     || '<tr><td align="center" style="padding:40px 56px 32px 56px;font-family:Georgia,''Times New Roman'',serif;font-size:14px;letter-spacing:0.5em;color:#B8AC95;">* * *</td></tr>'
     || '<tr><td style="padding:0 56px 12px 56px;font-family:system-ui,-apple-system,''Segoe UI'',sans-serif;font-size:11px;letter-spacing:0.18em;text-transform:uppercase;color:#8A7F6E;font-weight:600;">One thing to do</td></tr>'
     || '<tr><td style="padding:0 56px 28px 56px;font-family:Georgia,''Times New Roman'',serif;font-size:17px;line-height:28px;color:#1A1A1A;">The fastest way to know if {{product}} is for you is to try the one task that takes ninety seconds. Not a tour. Not a video. The real thing.</td></tr>'
     || '<tr><td style="padding:0 56px 8px 56px;"><a href="{{first_action_url}}" style="display:inline-block;background-color:#1A1A1A;color:#FAF9F6;font-family:system-ui,-apple-system,''Segoe UI'',sans-serif;font-size:15px;font-weight:600;letter-spacing:0.01em;text-decoration:none;padding:14px 28px;border-radius:999px;">Start the 90-second task &rarr;</a></td></tr>'
     || '<tr><td style="padding:8px 56px 0 56px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12px;color:#8A7F6E;letter-spacing:0.02em;">~90 sec &middot; no credit card &middot; no signup wall</td></tr>'
     || '<tr><td align="center" style="padding:48px 56px 32px 56px;font-family:Georgia,''Times New Roman'',serif;font-size:14px;letter-spacing:0.5em;color:#B8AC95;">* * *</td></tr>'
     || '<tr><td style="padding:0 56px 8px 56px;font-family:Georgia,''Times New Roman'',serif;font-size:17px;line-height:28px;color:#1A1A1A;font-style:italic;">Glad you&rsquo;re here,</td></tr>'
     || '<tr><td style="padding:0 56px 4px 56px;font-family:Georgia,''Times New Roman'',serif;font-size:24px;line-height:32px;color:#1A1A1A;letter-spacing:-0.01em;">{{founder_name}}</td></tr>'
     || '<tr><td style="padding:0 56px 56px 56px;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12px;color:#8A7F6E;">reply &rarr; <a href="mailto:{{reply_email}}" style="color:#8A7F6E;text-decoration:underline;">{{reply_email}}</a></td></tr>'
     || '</table>'
     || '<table role="presentation" width="600" align="center" cellpadding="0" cellspacing="0" border="0" style="width:600px;max-width:600px;margin:24px auto 0 auto;"><tr><td align="center" style="padding:16px 24px;font-family:system-ui,-apple-system,''Segoe UI'',sans-serif;font-size:12px;line-height:20px;color:#8A7F6E;">You&rsquo;re receiving this because you signed up for {{product}}.<br />Promise #4 (the bonus one): <a href="{{unsubscribe_url}}" style="color:#8A7F6E;text-decoration:underline;">one-click unsubscribe</a>, always honored.</td></tr></table></div>',
     '[{"name":"first_name","label":"First name","default":"Friend"},{"name":"product","label":"Product","default":"Postwave"},{"name":"plan_name","label":"Plan","default":"Starter"},{"name":"founder_name","label":"Sender name","default":"Harsh"},{"name":"reply_email","label":"Reply-to","default":"harsh@postwave.com"},{"name":"first_action_url","label":"First task URL","default":"https://app.postwave.com/onboarding"},{"name":"unsubscribe_url","label":"Unsubscribe URL","default":"https://postwave.com/unsubscribe"}]'::jsonb,
     ARRAY['welcome','trust','editorial','lowercase','minimal'],
     'welcome',
     true),

