     ||     '<tr><td width="56" valign="middle" style="height:56px;border-bottom:1px solid #ECECEC;padding:0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;color:#6B6B6B;">05</td><td valign="middle" style="height:56px;border-bottom:1px solid #ECECEC;padding:0 12px 0 0;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:14px;line-height:20px;color:#3A3A3A;">Automate a 3-step journey</td><td align="right" valign="middle" style="height:56px;border-bottom:1px solid #ECECEC;padding:0;"><span style="display:inline-block;background-color:transparent;border:1px solid #D4D4D4;color:#6B6B6B;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:14px;letter-spacing:0.08em;text-transform:uppercase;padding:5px 11px;border-radius:999px;">fri</span></td></tr>'
     ||   '</table>'
