     ||   '<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 8px 0;"><tr><td align="center" style="border-radius:999px;background-color:#0A0A0A;"><a href="{{tour_url}}" style="display:inline-block;padding:14px 28px;font-family:system-ui,-apple-system,Segoe UI,Helvetica,sans-serif;font-size:14px;line-height:18px;color:#FFFFFF;font-weight:600;text-decoration:none;border-radius:999px;letter-spacing:-0.005em;">Take the 90-second tour &rarr;</a></td></tr></table>'
