    -- 7. promotional-honest-math
    (NULL, 'promotional-honest-math',
     'Honest-Math Discount',
     'Anti-spam promo that opens with ''a discount feels weird, here''s the math'' — itemizes the offer line-by-line, explains why it exists, and includes a ''might not be right for you'' anti-fit paragraph.',
     'marketing',
     'A discount feels weird, so here''s the math',
     'We over-forecasted on infra. Loss is your gain — until Friday.',
     '<table role="presentation" width="600" align="center" cellpadding="0" cellspacing="0" border="0" style="width:600px;max-width:600px;margin:0 auto;background-color:#FFFFFF;font-family:system-ui,-apple-system,Segoe UI,sans-serif;">'
