     || '<tr><td style="padding:16px 40px 8px 40px;"><h1 style="margin:0;font-size:24px;line-height:32px;font-weight:600;color:#0F172A;letter-spacing:-0.01em;">A discount feels weird, so here&rsquo;s the math</h1></td></tr>'
     || '<tr><td style="padding:20px 40px 8px 40px;"><p style="margin:0;font-size:16px;line-height:26px;color:#334155;">{{reason_paragraph}}</p><p style="margin:16px 0 0 0;font-size:16px;line-height:26px;color:#334155;">We over-forecasted on infra this quarter. The capacity is already paid for, so we&rsquo;d rather move it than waste it. That&rsquo;s the whole reason. No urgency tricks, no fake scarcity &mdash; just a window that closes when it closes.</p></td></tr>'
     || '<tr><td style="padding:32px 40px 0 40px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%;border-collapse:collapse;"><tr><td style="height:44px;padding:12px 0;vertical-align:middle;"><span style="font-size:11px;line-height:14px;color:#64748B;text-transform:uppercase;letter-spacing:0.12em;font-weight:600;">Original</span></td><td align="right" style="height:44px;padding:12px 0;vertical-align:middle;"><span style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:18px;line-height:22px;color:#0F172A;font-variant-numeric:tabular-nums;">{{original_price}}</span></td></tr><tr><td style="height:44px;padding:12px 0;vertical-align:middle;"><span style="font-size:11px;line-height:14px;color:#64748B;text-transform:uppercase;letter-spacing:0.12em;font-weight:600;">Discount</span></td><td align="right" style="height:44px;padding:12px 0;vertical-align:middle;"><span style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:18px;line-height:22px;color:#0F172A;font-variant-numeric:tabular-nums;">&minus;&nbsp;{{discount_amount}}</span></td></tr><tr><td style="height:44px;padding:16px 0 12px 0;vertical-align:middle;border-top:1px solid #E2E8F0;"><span style="font-size:11px;line-height:14px;color:#64748B;text-transform:uppercase;letter-spacing:0.12em;font-weight:600;">Final</span></td><td align="right" style="height:44px;padding:16px 0 12px 0;vertical-align:middle;border-top:1px solid #E2E8F0;"><span style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:18px;line-height:22px;color:#0F766E;font-variant-numeric:tabular-nums;font-weight:600;">{{final_price}}</span></td></tr></table></td></tr>'
     || '<tr><td style="padding:36px 40px 0 40px;"><div style="font-size:11px;line-height:14px;color:#DC2626;text-transform:uppercase;letter-spacing:0.14em;font-weight:600;font-variant:small-caps;">Not right for you if&hellip;</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="width:100%;margin-top:14px;"><tr><td style="padding:6px 0;vertical-align:top;width:20px;"><span style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:14px;color:#94A3B8;">&mdash;</span></td><td style="padding:6px 0;font-size:15px;line-height:24px;color:#334155;">You&rsquo;re still evaluating whether the problem is worth solving. Wait until you&rsquo;re sure &mdash; the price will come back.</td></tr><tr><td style="padding:6px 0;vertical-align:top;width:20px;"><span style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:14px;color:#94A3B8;">&mdash;</span></td><td style="padding:6px 0;font-size:15px;line-height:24px;color:#334155;">You don&rsquo;t have time to onboard this month. Discounted or not, an unused tool is the most expensive one.</td></tr></table></td></tr>'
     || '<tr><td align="center" style="padding:36px 40px 8px 40px;"><a href="{{claim_url}}" style="display:inline-block;background-color:#0F766E;color:#FFFFFF;font-size:15px;line-height:20px;font-weight:600;text-decoration:none;padding:14px 28px;border-radius:999px;font-family:system-ui,-apple-system,Segoe UI,sans-serif;">Claim the price</a></td></tr>'
     || '<tr><td align="center" style="padding:4px 40px 0 40px;"><span style="font-size:14px;line-height:22px;color:#64748B;">or </span><a href="mailto:{{reply_email}}" style="font-size:14px;line-height:22px;color:#0F766E;text-decoration:underline;">reply to this email</a><span style="font-size:14px;line-height:22px;color:#64748B;"> with questions</span></td></tr>'
     || '<tr><td align="center" style="padding:28px 40px 8px 40px;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12px;line-height:16px;color:#64748B;letter-spacing:0.04em;">Window closes <span style="color:#0F172A;">{{deadline}}</span></div></td></tr>'
     || '<tr><td style="padding:24px 40px 8px 40px;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12px;color:#CBD5E1;letter-spacing:0.08em;">───────────────────────────</div></td></tr>'
     || '<tr><td align="center" style="padding:8px 40px 40px 40px;"><p style="margin:0;font-size:12px;line-height:18px;color:#94A3B8;">You&rsquo;re getting this because you opted in for product updates.<br/><a href="{{unsubscribe_url}}" style="color:#64748B;text-decoration:underline;">Unsubscribe</a></p></td></tr>'
     || '</table>',
     '[{"name":"original_price","label":"Original","default":"$49/mo"},{"name":"discount_amount","label":"Discount","default":"-$15/mo for 6 months"},{"name":"final_price","label":"Final","default":"$34/mo"},{"name":"reason_paragraph","label":"Reason","default":"We over-forecasted infra for Q2."},{"name":"deadline","label":"Deadline","default":"Friday, June 6, 11:59 PM PT"},{"name":"claim_url","label":"Claim URL","default":"https://postwave.com/offer/honest"},{"name":"reply_email","label":"Reply-to","default":"harsh@postwave.com"},{"name":"unsubscribe_url","label":"Unsubscribe URL","default":"https://postwave.com/unsubscribe"}]'::jsonb,
     ARRAY['promotional','restrained','honest','anti-spam','consultative'],
     'promotional',
     false),

