     || '<tr><td style="padding:0 40px 16px 40px;"><div style="font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;line-height:16px;letter-spacing:0.1em;text-transform:uppercase;color:#737373;font-weight:600;">─── What changed</div></td></tr>'
