     '[{"name":"first_name","label":"First name","default":"there"},{"name":"days_inactive","label":"Days inactive","default":"90 days"},{"name":"shipped_one","label":"Shipped 1","default":"A new audience builder"},{"name":"pause_url","label":"Pause URL","default":"https://postwave.com/preferences/pause"},{"name":"keep_url","label":"Keep URL","default":"https://postwave.com/preferences/keep"},{"name":"unsubscribe_url","label":"Unsubscribe URL","default":"https://postwave.com/unsubscribe"}]'::jsonb,
