     ||   '<p style="margin:0 0 12px 0;font-family:system-ui,-apple-system,Segoe UI,sans-serif;font-size:11px;line-height:14px;letter-spacing:0.1em;text-transform:uppercase;color:#4F46E5;font-weight:600;">Recent activity</p>'
